    55→  if (!match) return timeStr;
    56→  let h = parseInt(match[1]);
    57→  const m = parseInt(match[2]);
    58→  const period = match[3].toUpperCase();
    59→  if (period === 'PM' && h !== 12) h += 12;
    60→  if (period === 'AM' && h === 12) h = 0;
    61→  const date = new Date(base.getFullYear(), base.getMonth(), base.getDate(), h, m, 0, 0);
    62→  // If that date is already in the past, extend from now instead
    63→  const extendFrom = date.getTime() < Date.now() ? new Date() : date;
    64→  const newDate = new Date(extendFrom.getTime() + hours * 60 * 60 * 1000);
    65→  return newDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
